class EligibilityError(ValueError):
    __slots__ = ("code", "location")

    def __init__(self, code, location):
        self.code, self.location = code, location
        self.args = (code, location)


def _need(condition, code, location):
    if not condition:
        raise EligibilityError(code, location)


def _same(actual, expected, code, location):
    """Exact nested types as well as values; bool never aliases a typed integer."""
    _need(type(actual) is type(expected), code, location)
    if type(expected) is dict:
        _need(set(actual) == set(expected), code, location)
        for key in expected:
            _same(actual[key], expected[key], code, location + "/" + key)
    elif type(expected) is list:
        _need(len(actual) == len(expected), code, location)
        for index, item in enumerate(expected):
            _same(actual[index], item, code, location + "/" + str(index))
    else:
        _need(actual == expected, code, location)


def _json_shape(value, location, depth=0):
    """Bounded exact JSON tree; no coercion, subclasses, floats or cycles."""
    _need(depth <= 64, "InputShape", location)
    if value is None or type(value) in (str, int, bool):
        return
    if type(value) is list:
        for index, item in enumerate(value):
            _json_shape(item, location + "/" + str(index), depth + 1)
    elif type(value) is dict:
        for key, item in value.items():
            _need(type(key) is str, "InputShape", location)
            _json_shape(item, location + "/" + key, depth + 1)
    else:
        _need(False, "InputShape", location)


def _copy(value):
    return json.loads(json.dumps(value))


def _source_bindings(model):
    """Declared identities here; the separate validator hashes actual files."""
    _need("upstreamBindings" in model, "SourceBindingMissing", "upstreamBindings")
    rows = model["upstreamBindings"]
    _need(type(rows) is list, "SourceBindingMissing", "upstreamBindings")
    wanted = _REVIEWED["upstreamBindings"]
    files = []
    for row in rows:
        _need(type(row) is dict and set(row) == {"file", "bytes", "sha256"},
              "SourceIdentityMismatch", "upstreamBindings/shape")
        _need(type(row["file"]) is str, "SourceIdentityMismatch", "upstreamBindings/file")
        files.append(row["file"])
    _need(len(files) == len(wanted) and len(set(files)) == len(files)
          and set(files) == set(row["file"] for row in wanted),
          "SourceBindingMissing", "upstreamBindings/inventory")
    _same(rows, wanted, "SourceIdentityMismatch", "upstreamBindings")


def _inventory(model):
    rows, wanted = model["typedRequestMapping"], _REVIEWED["typedRequestMapping"]
    _need(type(rows) is list and len(rows) == len(wanted),
          "NodeInventoryMismatch", "typedRequestMapping")
    for index, (row, expected) in enumerate(zip(rows, wanted)):
        location = "typedRequestMapping/" + str(index)
        _need(type(row) is dict and set(row) == set(expected), "InputShape", location)
        for key in ("nodeId", "originalLogicalSiteId", "nodeKind"):
            _same(row[key], expected[key], "NodeInventoryMismatch", location + "/" + key)
    return rows, wanted


def _forms_and_routes(model, rows, wanted):
    _same(model["routes"], _REVIEWED["routes"], "CodecRouteMismatch", "routes")
    for row, expected in zip(rows, wanted):
        _same(row["routeId"], expected["routeId"], "CodecRouteMismatch", "route/" + str(row["nodeId"]))
    facts, reviewed = model["exactForms"], _REVIEWED["exactForms"]
    _need(type(facts) is list and len(facts) == len(reviewed), "UnsupportedForm", "exactForms")
    for index, (fact, expected) in enumerate(zip(facts, reviewed)):
        location = "exactForms/" + str(index)
        _need(type(fact) is dict and set(fact) == set(expected), "UnsupportedForm", location)
        for key in ("formId", "routeId"):
            _same(fact[key], expected[key], "UnsupportedForm", location + "/" + key)
    for row, expected in zip(rows, wanted):
        _same(row["formId"], expected["formId"], "UnsupportedForm", "form/" + str(row["nodeId"]))
    for index, (fact, expected) in enumerate(zip(facts, reviewed)):
        _same(fact["length"], expected["length"], "InstructionLengthMismatch", "exactForms/" + str(index) + "/length")
    for row, expected in zip(rows, wanted):
        _same(row["plannedLength"], expected["plannedLength"], "InstructionLengthMismatch", "length/" + str(row["nodeId"]))
    for index, (fact, expected) in enumerate(zip(facts, reviewed)):
        _same(fact, expected, "PrimaryEvidenceMismatch", "exactForms/" + str(index))
    _same(model["operandTypes"], _REVIEWED["operandTypes"], "OperandShape", "operandTypes")


def _operand_shape(descriptor, expected_kind, location):
    _need(type(descriptor) is dict and set(descriptor) == {"kind", "fields"},
          "OperandShape", location)
    kind, fields = descriptor["kind"], descriptor["fields"]
    _need(type(kind) is str and kind in _OPERAND_SLOTS and kind == expected_kind,
          "OperandKind", location + "/kind")
    _need(type(fields) is dict and set(fields) == set(_OPERAND_SLOTS[kind]),
          "OperandShape", location + "/fields")
    if kind == "AccumulatorA":
        return
    if kind == "TargetPC16" and fields["value"] is None:
        return  # Unresolved recipe, not a legal future constructor yet.
    for key, value in fields.items():
        _need(type(value) is int, "OperandShape", location + "/" + key)
    if kind in ("PageBit7", "PageBit5"):
        _need(0 <= fields["offset"] <= 255, "OperandRange", location + "/offset")
        _need(fields["bit"] == (7 if kind == "PageBit7" else 5),
              "FixedOperandMismatch", location + "/bit")
        return
    maximum = 65535 if kind in ("Immediate16", "TargetPC16", "ProgramTarget16") else 255
    _need(0 <= fields["value"] <= maximum, "OperandRange", location + "/value")
    if kind in ("Register0", "Register1"):
        _need(fields["value"] == (0 if kind == "Register0" else 1),
              "FixedOperandMismatch", location + "/register")
    if kind == "EvenPageOffset8":
        _need(fields["value"] % 2 == 0, "OddWordOffsetOutsideProfile", location + "/alignment")


def _descriptors(rows, wanted, static):
    spans = {row["nodeId"]: row for row in static["nodeSpans"]}
    branches = {row["nodeId"]: row for row in static["branchRows"]}
    resolved = {}
    # Shape/kind/width checks for the entire inventory precede reviewed-value checks.
    for row, expected in zip(rows, wanted):
        node, descriptors = row["nodeId"], row["operandDescriptors"]
        _need(type(descriptors) is list and len(descriptors) == len(expected["operandDescriptors"]),
              "OperandShape", "operands/" + str(node))
        for index, (descriptor, fixed) in enumerate(zip(descriptors, expected["operandDescriptors"])):
            _operand_shape(descriptor, fixed["kind"], "operands/" + str(node) + "/" + str(index))
    for row, expected in zip(rows, wanted):
        node = row["nodeId"]
        _same(row["relocatedTargetNodeId"], expected["relocatedTargetNodeId"],
              "BranchTargetMismatch", "branch/" + str(node) + "/logicalTarget")
        operands = _copy(row["operandDescriptors"])
        for index, (operand, fixed) in enumerate(zip(operands, expected["operandDescriptors"])):
            kind = operand["kind"]
            code = ("BranchTargetMismatch" if kind == "TargetPC16" else
                    "ContinuationMismatch" if kind == "ProgramTarget16" else "OperandValueMismatch")
            _same(operand["fields"], fixed["fields"], code, "operands/" + str(node) + "/" + str(index) + "/reviewedValue")
            if kind == "TargetPC16":
                target_node = row["relocatedTargetNodeId"]
                _need(target_node in spans and node in branches, "BranchTargetMismatch", "branch/" + str(node))
                target = spans[target_node]["assignedPC"]
                branch = branches[node]
                _need(target == branch["assignedTargetPC"] and target_node == branch["targetNodeId"],
                      "BranchTargetMismatch", "branch/" + str(node) + "/assignedTarget")
                _need(0 <= target <= 65535 and -128 <= target - spans[node]["endExclusive"] <= 127,
                      "Rel8OutOfRange", "branch/" + str(node) + "/mathematicalDistance")
                operand["fields"]["value"] = target
        resolved[node] = operands
    return resolved


def _projection_obligations(rows, wanted, static, request):
    spans = {row["nodeId"]: row for row in static["nodeSpans"]}
    dd = {row["nodeId"]: row for row in static["ddFlow"]}
    for row, expected in zip(rows, wanted):
        node = row["nodeId"]
        for key in ("originOffset", "gapCoefficient"):
            _same(row[key], expected[key], "OriginProjectionMismatch", "origin/" + str(node) + "/" + key)
        computed = request["syntheticBase"] + row["originOffset"] + row["gapCoefficient"] * request["gap"]
        _need(computed == spans[node]["assignedPC"], "OriginProjectionMismatch", "origin/" + str(node))
    for row, expected in zip(rows, wanted):
        node = row["nodeId"]
        _same(row["incomingDDDomain"], expected["incomingDDDomain"],
              "DDProjectionMismatch", "dd/" + str(node) + "/declared")
        actual = dd[node]["incomingMay"]
        _same(actual, request["initialDD"] if node == rows[0]["nodeId"] else [0],
              "DDProjectionMismatch", "dd/" + str(node) + "/derived")
        _need(all(type(scalar) is int and scalar in row["incomingDDDomain"] for scalar in actual),
              "DDProjectionMismatch", "dd/" + str(node) + "/scalar")
        if node != rows[0]["nodeId"]:
            _need(dd[node]["incomingMust"] == 0, "DDProjectionMismatch", "dd/" + str(node) + "/must")
    for row, expected in zip(rows, wanted):
        node = row["nodeId"]
        actual = [edge["to"] for edge in static["edgeRows"] if edge["from"] == node]
        _same(row["successorIds"], expected["successorIds"], "CFGRelationMismatch", "successors/" + str(node))
        _same(row["successorIds"], actual, "CFGRelationMismatch", "successors/" + str(node) + "/derived")
    for row, expected in zip(rows, wanted):
        _same(row["primary"], expected["primary"], "PrimaryEvidenceMismatch", "primary/" + str(row["nodeId"]))


def _policies(model, static):
    for field, code in (
        ("primaryEvidence", "PrimaryEvidenceMismatch"),
        ("atomicity", "AtomicityPolicyMismatch"),
        ("futurePrimaryVerification", "FuturePrimaryVerificationMismatch"),
        ("futureDecodeVerification", "FutureDecodeVerificationMismatch"),
        ("futureOrderedEffectsVerification", "EffectVerificationPolicyMismatch"),
        ("inheritedContextAndEffectObligations", "ContextObligationMismatch"),
        ("allowedSyntheticGeometry", "RuntimePolicyMismatch"),
        ("runtimeExclusions", "RuntimePolicyMismatch"),
        ("nativeOwnerRestrictions", "RuntimePolicyMismatch"),
        ("historicalPreservation", "RuntimePolicyMismatch"),
        ("proofLevels", "RuntimePolicyMismatch"),
        ("decisionMatrix", "RuntimePolicyMismatch"),
    ):
        _same(model[field], _REVIEWED[field], code, field)
    obligations = model["inheritedContextAndEffectObligations"]
    _same(obligations["context"], static["contextObligations"], "ContextObligationMismatch", "context/derived")
    effects = model["futureOrderedEffectsVerification"]
    _same([len(path["orderedWrites"]) for path in static["paths"]], effects["orderedWriteCounts"],
          "MemoryEffectMismatch", "effects/derivedWriteCounts")
    _same([path["composedNodeCount"] for path in static["paths"]], effects["composedPathCounts"],
          "CFGRelationMismatch", "effects/derivedPathCounts")
    _need(sum(row["plannedLength"] for row in model["typedRequestMapping"]) == 51
          and static["counts"]["denseLength"] == 51 and static["counts"]["totalLength"] == 51,
          "InstructionLengthMismatch", "length/closure")


def _node_plans(rows, operands, static):
    spans = {row["nodeId"]: row for row in static["nodeSpans"]}
    domains = {row["nodeId"]: row["incomingMay"] for row in static["ddFlow"]}
    plans = []
    for row in rows:
        node = row["nodeId"]
        typed, origin = operands[node], spans[node]["assignedPC"]
        variants = []
        for scalar in domains[node]:
            if row["routeId"] == "A":
                fields = {"reviewed_form_id": {"enumClass": "FormId", "value": row["formId"]},
                          "typed_operands": {"container": "tuple", "items": _copy(typed)},
                          "incoming_dd": scalar, "origin_pc": origin}
                request_class = "EncoderRequest"
            else:
                fields = {"target": _copy(typed[0]), "origin_pc": origin, "incoming_dd": scalar}
                request_class = "DirectJEncodeRequest"
            variants.append({"requestClass": request_class, "fields": fields})
        plans.append({"nodeId": node, "originalLogicalSiteId": row["originalLogicalSiteId"],
                      "nodeKind": row["nodeKind"], "routeId": row["routeId"], "formId": row["formId"],
                      "assignedPC": origin, "endExclusive": spans[node]["endExclusive"],
                      "plannedLength": spans[node]["length"], "incomingDDDomain": list(domains[node]),
                      "typedOperands": _copy(typed), "successorIds": _copy(row["successorIds"]),
                      "relocatedTargetNodeId": row["relocatedTargetNodeId"], "primary": _copy(row["primary"]),
                      "requestVariants": variants})
    return plans


def prepare_composite_emission_plan(original_ir, composition_contract, eligibility_contract, request):
    """Validate one closed static plan, returning no bytes or runtime authority."""
    for label, value in (("original_ir", original_ir), ("composition_contract", composition_contract),
                         ("eligibility_contract", eligibility_contract), ("request", request)):
        _json_shape(value, label)
        _need(type(value) is dict, "InputShape", label)
    _source_bindings(eligibility_contract)
    _need(set(_REVIEWED).issubset(eligibility_contract), "InputShape", "eligibility_contract/requiredGroups")
    _need(request.get("classification") == "InventedOnlyCompositeEmissionEligibility",
          "RequestDomain", "request/classification")
    inherited_request = _copy(request)
    inherited_request["classification"] = "InventedOnlyStaticComposition"
    try:
        static = evaluate_composition(original_ir, composition_contract, inherited_request)
    except CompositionError as error:
        raise EligibilityError(error.code, error.path) from error
    # Real inherited relation refusals above cannot be masked by a policy failure.
    _need(request["syntheticBase"] == 4096 and request["gap"] == 0,
          "LayoutNotAllowlisted", "request/reviewedInventedGeometry")
    rows, wanted = _inventory(eligibility_contract)
    _forms_and_routes(eligibility_contract, rows, wanted)
    operands = _descriptors(rows, wanted, static)
    _projection_obligations(rows, wanted, static, request)
    _policies(eligibility_contract, static)
    # This identity guard is last, never a substitute for the preceding checks.
    _same(eligibility_contract, _REVIEWED, "MetadataMismatch", "eligibility_contract")
    plans = _node_plans(rows, operands, static)
    retained = {field: _copy(static[field]) for field in
                ("componentSpans", "gap", "edgeRows", "branchRows", "paths", "ddFlow", "flagFlow",
                 "contextObligations", "anchorObservations", "permissions")}
    counts = _copy(static["counts"])
    counts.update(routeANodes=sum(row["routeId"] == "A" for row in plans),
                  routeBNodes=sum(row["routeId"] == "B" for row in plans),
                  totalRequestVariants=sum(len(row["requestVariants"]) for row in plans),
                  unresolvedTypedMappings=0, syntheticEligibleLayouts=1)
    return {"classification": "ReviewedStatic20NodeTypedEmissionPlan",
            "verdict": "SyntheticCompositeEmissionEligibleForSeparateMilestone", "nodePlans": plans,
            **retained, "counts": counts,
            "futureVerification": {"primary": _copy(eligibility_contract["futurePrimaryVerification"]),
                                   "decode": _copy(eligibility_contract["futureDecodeVerification"]),
                                   "atomicity": _copy(eligibility_contract["atomicity"]),
                                   "orderedEffects": "SeparateFutureProof_NotByteIdentity_NotExecuted"},
            "runtimeStatus": _copy(_RUNTIME_STATUS)}
